final class BackendOSTestPortStoreIndex: BackendOSTestPortFixture {
    let now = BackendAppStoreIndex.date("2026-08-28T12:00:00.000Z")!
    var row: NativeRPCValue { .object([
        .init("id", .string("acme/pr-review")), .init("publisher", .string("acme")), .init("listedBy", .string("acme")), .init("kind", .string("skill")), .init("name", .string("Pull request review")), .init("summary", .string("Reads a diff and writes the review you would have written.")),
        .init("version", .string("1.0.0")), .init("licence", .string("MIT")), .init("category", .string("code")), .init("tags", .array([.string("review")])), .init("agents", .array([.string("claude")])), .init("platforms", .array([.string("darwin"), .string("linux")])), .init("tier", .number(1)), .init("needs", .array([])), .init("cost", .string("free")), .init("costNote", .null), .init("delivery", .string("repo")),
        .init("source", .object([.init("repo", .string("https://github.com/acme/pr-review")), .init("commit", .string(String(repeating: "a", count: 40))), .init("path", .string(".")), .init("host", .string("github.com"))])),
        .init("artifact", .object([.init("url", .string("https://codeload.github.com/acme/pr-review/zip/" + String(repeating: "a", count: 40))), .init("sha256", .string(String(repeating: "b", count: 64))), .init("bytes", .number(2048)), .init("files", .number(4)), .init("unpacked", .number(8192))])),
        .init("install", .object([.init("dir", .string("skills/pr-review"))])), .init("network", .array([])), .init("publishedAt", .string("2026-08-01T00:00:00.000Z")), .init("updatedAt", .string("2026-08-20T00:00:00.000Z"))]) }
    func document(_ patch: NativeRPCValue = .object([])) -> NativeRPCValue { NativeRPCValue.object([.init("v", .number(1)), .init("serial", .number(7)), .init("issuedAt", .string("2026-08-27T00:00:00.000Z")), .init("expiresAt", .null), .init("generator", .string("terminaldeck-commons 0.1.0")), .init("truncated", .bool(false)), .init("items", .array([row])), .init("revoked", .array([]))]).merging(patch) }
    func envelope(_ document: NativeRPCValue, stranger: Bool = false) throws -> String {
        let seed = stranger ? Data(repeating: 42, count: 32) : Data(SHA256.hash(data: Data(BackendSharedStoreKeys.developmentPhrase.utf8)))
        let key = try Curve25519.Signing.PrivateKey(rawRepresentation: seed), bytes = try document.encodedJSON(), signature = try key.signature(for: bytes)
        return NativeRPCValue.object([.init("v", .number(1)), .init("keyId", .string("td-store-dev-1")), .init("alg", .string("ed25519")), .init("sig", .string(signature.base64EncodedString())), .init("signed", .string(bytes.base64EncodedString()))]).compact
    }
    func checked(_ document: NativeRPCValue) throws -> NativeRPCValue { BackendAppStoreIndex.check(try envelope(document), keys: [BackendSharedStoreKeys.development], now: now).wire }
    func refused(_ document: NativeRPCValue) throws -> String { let result = try checked(document); XCTAssertEqual(result["ok"].bool, false); return result["why"].string ?? "" }
    func one(_ patch: NativeRPCValue) -> NativeRPCValue { document(.object([.init("items", .array([row.merging(patch)]))])) }
    func cache(_ root: URL, fetch: @escaping BackendAppStoreIndexCache.Fetch = { _, _ in .init(ok: false, message: "the store could not be reached") }) -> BackendAppStoreIndexCache { .init(userData: root, writable: true, keys: [BackendSharedStoreKeys.development], fetch: fetch) }
    func testStoreIndex124GoodSignatureNormalizedInstallAndKey() throws { let result = try checked(document()); XCTAssertEqual(result["ok"].bool, true); XCTAssertEqual(result["keyId"].string, "td-store-dev-1"); XCTAssertEqual(result["index"]["items"].elements?.count, 1); XCTAssertEqual(result["index"]["items"].elements?.first?["install"], .object([.init("kind", .string("skill")), .init("dir", .string("skills/pr-review"))])); XCTAssertEqual(result["stale"], .null) }
    func testStoreIndex135OneFlippedSignedBitRefuses() throws { var raw = try NativeRPCValue.parseJSON(Data(envelope(document()).utf8)), bytes = Data(base64Encoded: raw["signed"].string!)!; bytes[20] ^= 1; raw = raw.setting("signed", .string(bytes.base64EncodedString())); XCTAssertEqual(BackendAppStoreIndex.check(raw.compact, keys: [BackendSharedStoreKeys.development], now: now).wire["why"].string, "this catalogue was not signed by Terminal Deck, so it was not used") }
    func testStoreIndex145UnknownSigningKeyRefuses() throws { let result = BackendAppStoreIndex.check(try envelope(document(), stranger: true), keys: [BackendSharedStoreKeys.development], now: now).wire; XCTAssertTrue(result["why"].string?.contains("not signed by Terminal Deck") == true) }
    func testStoreIndex150SecondSlotRotationAccepted() throws { let older = BackendSharedStoreKey(id: "td-store-old", hex: String(repeating: "c", count: 64), because: "a retired key, in tests"), result = BackendAppStoreIndex.check(try envelope(document()), keys: [older, BackendSharedStoreKeys.development], now: now).wire; XCTAssertEqual(result["ok"].bool, true); XCTAssertEqual(result["keyId"].string, "td-store-dev-1") }
    func testStoreIndex157NoTrustedKeyRefuses() throws { XCTAssertEqual(BackendAppStoreIndex.check(try envelope(document()), keys: [], now: now).wire["why"].string, "this build carries no key to check a catalogue with") }
    func testStoreIndex168DevelopmentKeyRequiresUnpackagedOptIn() throws {
        let text = try envelope(document()), byDefault = BackendAppStoreIndex.check(text, now: now).wire; XCTAssertEqual(byDefault["ok"].bool, false); XCTAssertTrue(byDefault["why"].string?.contains("not signed by Terminal Deck") == true)
        let asked = [BackendSharedStoreKeys.environmentKey: "1"], packaged = BackendAppStoreIndex.check(text, keys: BackendSharedStoreKeys.keys(environment: asked, packaged: true), now: now).wire, local = BackendAppStoreIndex.check(text, keys: BackendSharedStoreKeys.keys(environment: asked, packaged: false), now: now).wire
        XCTAssertEqual(packaged["ok"].bool, false); XCTAssertEqual(local["ok"].bool, true); XCTAssertEqual(local["keyId"].string, "td-store-dev-1")
    }
    func testStoreIndex180UnknownAlgorithmRefuses() throws { let raw = try NativeRPCValue.parseJSON(Data(envelope(document()).utf8)).setting("alg", .string("rsa")); XCTAssertEqual(BackendAppStoreIndex.check(raw.compact, keys: [BackendSharedStoreKeys.development], now: now).wire["why"].string, "this catalogue is signed with rsa, which this app does not check") }
    func testStoreIndex185ShortSignatureRefusesBeforeCrypto() { XCTAssertNil(BackendAppStoreIndex.verify(signed: Data("x".utf8), signature: Data(repeating: 0, count: 10), keys: [BackendSharedStoreKeys.development]).key) }
    func testStoreIndex191OldSerialRefuses() throws { let result = BackendAppStoreIndex.check(try envelope(document(.object([.init("serial", .number(6))]))), keys: [BackendSharedStoreKeys.development], highWater: 7, now: now).wire; XCTAssertTrue(result["why"].string?.contains("older list than one this machine has already seen") == true) }
    func testStoreIndex195ReplayNamesWithdrawalRisk() throws { let result = BackendAppStoreIndex.check(try envelope(document(.object([.init("serial", .number(1))]))), keys: [BackendSharedStoreKeys.development], highWater: 7, now: now).wire; XCTAssertTrue(result["why"].string?.contains("put back something that was withdrawn") == true) }
    func testStoreIndex199SameSerialAccepted() throws { XCTAssertEqual(BackendAppStoreIndex.check(try envelope(document()), keys: [BackendSharedStoreKeys.development], highWater: 7, now: now).wire["ok"].bool, true) }
    func testStoreIndex205FortyDayAgeIsReported() throws { let result = try checked(document(.object([.init("issuedAt", .string(BackendAppSettingsStore.iso(now - 40 * 86_400_000)))]))); XCTAssertEqual(result["ok"].bool, true); XCTAssertEqual(result["stale"].string, "This list is 40 days old.") }
    func testStoreIndex211FutureDateIsReported() throws { let result = try checked(document(.object([.init("issuedAt", .string(BackendAppSettingsStore.iso(now + 86_400_000)))]))); XCTAssertEqual(result["ok"].bool, true); XCTAssertTrue(result["stale"].string?.contains("dated in the future") == true) }
    func testStoreIndex217ExpiredDateIsReported() throws { let result = try checked(document(.object([.init("expiresAt", .string(BackendAppSettingsStore.iso(now - 60_000)))]))); XCTAssertEqual(result["ok"].bool, true); XCTAssertTrue(result["stale"].string?.contains("passed the date it was good until") == true) }
    func testStoreIndex223ThisMorningNotStale() { XCTAssertNil(BackendAppStoreIndex.staleness(.object([.init("issuedAt", .string(BackendAppSettingsStore.iso(now - 3_600_000))), .init("expiresAt", .null)]), now: now)) }
    func testStoreIndex229UnknownTopLevelKeyNamed() throws { XCTAssertEqual(try refused(document(.object([.init("hydrate", .string("https://example.com/more.json"))]))), "the catalogue has a key this app does not know about: hydrate") }
    func testStoreIndex235UnknownFormatNamed() throws { XCTAssertEqual(try refused(document(.object([.init("v", .number(2))]))), "this catalogue is written for format 2, and this app reads format 1") }
    func testStoreIndex239UnknownRowKeyNamed() throws { XCTAssertEqual(try refused(one(.object([.init("sponsored", .bool(true))]))), "item 1 has a key this app does not know about: sponsored") }
    func testStoreIndex245PublisherNamespaceRefuses() throws { XCTAssertTrue(try refused(one(.object([.init("id", .string("someone-else/pr-review"))]))).contains("must be written acme/<id>")) }
