    func testStoreIndex257TierFloorRefuses() throws {
        let hooks = row.setting("kind", .string("hooks")).setting("tier", .number(1)).setting("needs", .array([.string("runs-scripts")])).setting("install", .object([.init("script", .string("hooks/notify.mjs")), .init("events", .array([.string("SessionStart")])), .init("runtime", .string("node"))]))
        XCTAssertEqual(try refused(document(.object([.init("items", .array([hooks]))]))), "item 1 calls itself tier 1, and a hooks can never be less than 3")
