    func testStoreIndex288ArrivedBytesCap() { let huge: NativeRPCValue = .object([.init("v", .number(1)), .init("keyId", .string("x")), .init("alg", .string("ed25519")), .init("sig", .string("")), .init("signed", .string(String(repeating: "x", count: BackendAppStoreIndex.maxBytes)))]); XCTAssertEqual(BackendAppStoreIndex.check(huge.compact, keys: [BackendSharedStoreKeys.development], now: now).wire["why"].string, "this catalogue is larger than this app will read") }
    func testStoreIndex293JunkNeverThrows() { for bytes in ["", "{", "null", "[]", #"{"v":1}"#] { XCTAssertEqual(BackendAppStoreIndex.check(bytes, keys: [BackendSharedStoreKeys.development], now: now).wire["ok"].bool, false) } }
    func testStoreIndex299SignedWithdrawalAndAbsentWithdrawal() throws {
        let result = try checked(document(.object([.init("revoked", .array([.object([.init("id", .string("acme/pr-review")), .init("version", .string("*")), .init("reason", .string("The publisher asked for it to come down."))])]))]))); XCTAssertEqual(result["ok"].bool, true)
        XCTAssertTrue(BackendAppStoreIndex.revocation(result["index"], id: "acme/pr-review", version: "1.0.0")?["reason"].string?.contains("asked for it") == true); XCTAssertNil(BackendAppStoreIndex.revocation(result["index"], id: "acme/other", version: "1.0.0"))
    }
    var archive: Data { Data("the archive".utf8) }
    var digest: String { SHA256.hash(data: archive).map { String(format: "%02x", $0) }.joined() }
    func testStoreIndex316CorrectBytesCaseInsensitiveDigest() { XCTAssertTrue(BackendAppStoreIndex.artifactMatches(archive, expectedHex: digest)); XCTAssertTrue(BackendAppStoreIndex.artifactMatches(archive, expectedHex: digest.uppercased())) }
    func testStoreIndex321OneChangedByteRefuses() { XCTAssertFalse(BackendAppStoreIndex.artifactMatches(Data("the archivf".utf8), expectedHex: digest)) }
