    func testStoreIndex345CacheRoundTripAndFetchTime() async throws {
        let root = try scratch(), cache = self.cache(root); let absent = await cache.hasCache(); XCTAssertFalse(absent); try await cache.write(envelope: envelope(document()), serial: 7, at: now)
        let present = await cache.hasCache(), kept = await cache.read(now: now), high = await cache.highWater(); XCTAssertTrue(present); XCTAssertNotNil(kept); XCTAssertEqual(kept?["savedAt"].string, BackendAppSettingsStore.iso(now)); XCTAssertEqual(kept?["index"]["serial"].number, 7); XCTAssertEqual(high, 7)
    }
    func testStoreIndex357HighWaterNeverDecreases() async throws { let root = try scratch(), cache = self.cache(root); try await cache.write(envelope: envelope(document(.object([.init("serial", .number(9))]))), serial: 9, at: now); try await cache.write(envelope: envelope(document(.object([.init("serial", .number(2))]))), serial: 2, at: now); let high = await cache.highWater(); XCTAssertEqual(high, 9) }
    func testStoreIndex364CacheTamperRefuses() async throws {
        let root = try scratch(), cache = self.cache(root); try await cache.write(envelope: envelope(document()), serial: 7, at: now); let file = await cache.file
        var raw = try disk(file), env = try NativeRPCValue.parseJSON(Data(raw["envelope"].string!.utf8)), bytes = Data(base64Encoded: env["signed"].string!)!; bytes[15] ^= 2; env = env.setting("signed", .string(bytes.base64EncodedString())); raw = raw.setting("envelope", .string(env.compact)); try raw.encodedJSON().write(to: file)
        let kept = await cache.read(now: now); XCTAssertNil(kept)
    }
    func testStoreIndex378NoCacheNoHighWater() async throws { let cache = self.cache(try scratch()), kept = await cache.read(now: now), high = await cache.highWater(); XCTAssertNil(kept); XCTAssertEqual(high, 0) }
    func serving(_ root: URL, text: String) -> BackendAppStoreIndexCache { cache(root) { url, _ in XCTAssertEqual(url, "http://127.0.0.1:8931/store/index.json"); return .init(ok: true, text: text) } }
    func testStoreIndex415FetchCheckKeep() async throws { let root = try scratch(), cache = serving(root, text: try envelope(document())), result = await cache.load(base: "http://127.0.0.1:8931", now: now), high = await cache.highWater(); XCTAssertEqual(result["ok"].bool, true); XCTAssertEqual(result["from"].string, "store"); XCTAssertEqual(result["because"], .null); XCTAssertEqual(high, 7) }
    func testStoreIndex426OfflineKeptHasOriginalFetchTime() async throws { let root = try scratch(), online = serving(root, text: try envelope(document())); _ = await online.load(base: "http://127.0.0.1:8931", now: now); let offline = self.cache(root), result = await offline.load(base: "http://127.0.0.1:8931", now: now); XCTAssertEqual(result["ok"].bool, true); XCTAssertEqual(result["from"].string, "kept"); XCTAssertEqual(result["at"].string, BackendAppSettingsStore.iso(now)); XCTAssertEqual(result["because"].string, "the store could not be reached") }
    func testStoreIndex438ForgedFetchUsesKeptAndNamesSignatureFailure() async throws { let root = try scratch(), online = serving(root, text: try envelope(document())); _ = await online.load(base: "http://127.0.0.1:8931", now: now); let forged = serving(root, text: try envelope(document(.object([.init("serial", .number(8))])), stranger: true)), result = await forged.load(base: "http://127.0.0.1:8931", now: now); XCTAssertEqual(result["ok"].bool, true); XCTAssertEqual(result["from"].string, "kept"); XCTAssertTrue(result["because"].string?.contains("not signed by Terminal Deck") == true); XCTAssertEqual(result["index"]["serial"].number, 7) }
    func testStoreIndex452NothingKeptOrBelievableRefuses() async throws { let root = try scratch(), cache = serving(root, text: try envelope(document(), stranger: true)), result = await cache.load(base: "http://127.0.0.1:8931", now: now); XCTAssertEqual(result["ok"].bool, false); XCTAssertTrue(result["why"].string?.contains("not signed by Terminal Deck") == true) }
    func testStoreIndex460ReplayFromStoreUsesNewerKept() async throws { let root = try scratch(), online = serving(root, text: try envelope(document(.object([.init("serial", .number(9))])))); _ = await online.load(base: "http://127.0.0.1:8931", now: now); let replay = serving(root, text: try envelope(document(.object([.init("serial", .number(3))])))), result = await replay.load(base: "http://127.0.0.1:8931", now: now); XCTAssertEqual(result["ok"].bool, true); XCTAssertEqual(result["from"].string, "kept"); XCTAssertEqual(result["index"]["serial"].number, 9); XCTAssertTrue(result["because"].string?.contains("older list") == true) }
    func acceptedRow(_ patch: NativeRPCValue) throws -> NativeRPCValue { let result = try checked(one(patch)); XCTAssertEqual(result["ok"].bool, true, result["why"].string ?? ""); return result["index"]["items"].elements?.first ?? .missing }
